const repo = $env.GITHUB_REPO || 'owner/repo';
const lang = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
if (!/^[^/]+\/[^/]+$/.test(repo)) throw new Error('GITHUB_REPO must be owner/repo');
if (!['EN','FR'].includes(lang)) throw new Error('SUMMARY_LANGUAGE must be EN or FR');
const until = new Date();
const since = new Date(until.getTime() - 7*24*60*60*1000);
const base = `https://api.github.com/repos/${repo}`;
return [
 {json:{kind:'commits',repo,lang,since:since.toISOString(),until:until.toISOString(),url:`${base}/commits?since=${encodeURIComponent(since.toISOString())}&until=${encodeURIComponent(until.toISOString())}&per_page=100`}},
 {json:{kind:'issues',repo,lang,since:since.toISOString(),until:until.toISOString(),url:`${base}/issues?state=closed&since=${encodeURIComponent(since.toISOString())}&per_page=100`}},
 {json:{kind:'pulls',repo,lang,since:since.toISOString(),until:until.toISOString(),url:`${base}/pulls?state=closed&sort=updated&direction=desc&per_page=100`}}
];

const rows = $input.all();
const buckets={commits:[],issues:[],pulls:[]};
let repo='', lang='EN', since='', until='';
for (const item of rows) {
  const src=item.pairedItem?.item ?? 0;
  const meta=$('Build weekly API requests').all()[src]?.json || {};
  repo=meta.repo||repo; lang=meta.lang||lang; since=meta.since||since; until=meta.until||until;
  const body=item.json;
  const data=Array.isArray(body)?body:(body.body && Array.isArray(body.body)?body.body:[]);
  if (meta.kind==='commits') buckets.commits.push(...data.map(x=>({sha:x.sha?.slice(0,7),message:x.commit?.message?.split('\n')[0],author:x.commit?.author?.name,url:x.html_url})));
  if (meta.kind==='issues') buckets.issues.push(...data.filter(x=>!x.pull_request).map(x=>({number:x.number,title:x.title,url:x.html_url,closed_at:x.closed_at})));
  if (meta.kind==='pulls') buckets.pulls.push(...data.filter(x=>x.merged_at && new Date(x.merged_at)>=new Date(since)).map(x=>({number:x.number,title:x.title,url:x.html_url,merged_at:x.merged_at,user:x.user?.login})));
}
const instruction=lang==='FR'?'Rédige le résumé en français.':'Write the summary in English.';
const prompt=`You are preparing a weekly engineering update for ${repo}. ${instruction} Be factual; do not invent causes or impact. Cover shipped work, closed issues, themes, and what to watch next.\n\nWindow: ${since} to ${until}\n\nDATA:\n${JSON.stringify(buckets,null,2)}`;
return [{json:{repo,lang,since,until,prompt,counts:{commits:buckets.commits.length,closedIssues:buckets.issues.length,mergedPRs:buckets.pulls.length}}}];

const body=$json.body || $json;
const text=body.content?.filter(x=>x.type==='text').map(x=>x.text).join('\n') || '';
if (!text) throw new Error('Claude response contained no text');
const meta=$('Build Claude prompt').first().json;
return [{json:{text,repo:meta.repo,counts:meta.counts,window:`${meta.since} → ${meta.until}`}}];

